    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # A source row has a solid non-background run reaching the right edge.
    sources = []
    for r, row in enumerate(grid):
        if row[-1] == bg:
            continue
        color = row[-1]
        start = w - 1
        while start > 0 and row[start - 1] == color:
            start -= 1
        if w - start >= 3:
            sources.append((r, color, start))

    # A matching row may be shifted horizontally. Compare its entire observed
    # pattern through its last foreground cell; only the missing right suffix
    # is drawn, in marker color 1.
    for tr, target in enumerate(grid):
        occupied = [c for c, value in enumerate(target) if value != bg]
        if not occupied:
            continue
        last = occupied[-1]
        if last == w - 1:
            continue
        first = occupied[0]

