 "content": "def transform(grid):
    """Highlight the background-side differences of repeated aligned rows."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(value for row in grid for value in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Repeated row motifs in these puzzles are aligned with a small horizontal
    # offset and share a long exact prefix. The later/earlier row is selected
    # by which side is background at a disagreement; only that background cell
    # is marked, and only beyond the shared prefix.
    for r1 in range(h):
        if all(value == bg for value in grid[r1]):
            continue
        for r2 in range(r1 + 3, h):
            if all(value == bg for value in grid[r2]):
                continue
            best = None
            for shift in range(-2, 3):  # compare row1[c] with row2[c + shift]
                c = 0
                while c < w:
                    d = c + shift
                    if not (0 <= d < w) or ((grid[r1][c] == bg) != (grid[r2][d] == bg)):
                        c += 1
                        continue
                    start = c
                    foreground = 0
                    while c < w:
                        d = c + shift
                        if not (0 <= d < w) or ((grid[r1][c] == bg) != (grid[r2][d] == bg)):
                            break
                        if grid[r1][c] != bg:
                            foreground += 1
                        c += 1
                    length = c - start
                    # Require a substantive shared motif, not a common blank run.
                    if length >= 5 and foreground >= 2:
                        score = (length, foreground, -abs(shift), -start)
                        if best is None or score > best[0]:
                            best = (score, c, shift)
                    if c == start:
                        c += 1

            if best is None:
                continue
            _, end, shift = best
            # After the exact shared run, mark only the cell which is background
            # while its aligned counterpart carries the pattern.
            for c in range(end, w):
                d = c + shift
                if not 0 <= d < w:
                    continue
                a, b = grid[r1][c], grid[r2][d]
                if a == bg and b != bg:
                    out[r1][c] = 1
                elif b == bg and a != bg:
                    out[r2][d] = 1

    return out

if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin)), separators=(",", ":")))
