    """Transfer the unmatched tail of one repeated horizontal panel into its twin."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(value for row in grid for value in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Consecutive rows containing the non-background motif form a panel/band.
    bands = []
    r = 0
    while r < h:
        if all(value == bg for value in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(value != bg for value in grid[r]):
            r += 1
        bands.append((start, r))

    best_pair = None
    for i, (a0, a1) in enumerate(bands):
        for b0, b1 in bands[i + 1:]:
            if a1 - a0 != b1 - b0:
                continue
            height = a1 - a0
            for shift in range(-2, 3):  # map A column c to B column c + shift
                common = 0
                prefix = 0
                fg_shared = 0
                a_excess = 0
                b_excess = 0
                for dr in range(height):
                    row_a, row_b = grid[a0 + dr], grid[b0 + dr]
                    # Longest exact occupancy prefix under this alignment.
                    c = max(0, -shift)
                    first_mismatch = None
                    while c < w and c + shift < w:
                        va, vb = row_a[c], row_b[c + shift]
                        if (va != bg) != (vb != bg):
                            first_mismatch = c
                            break
                        common += 1
                        if va != bg:
                            fg_shared += 1
                        c += 1
                    prefix += c - max(0, -shift)
                    if first_mismatch is not None:
                        for ca in range(first_mismatch, w):
                            cb = ca + shift
                            if not 0 <= cb < w:
                                continue
                            va, vb = row_a[ca], row_b[cb]
                            if va != bg and vb == bg:
                                a_excess += 1
                            elif vb != bg and va == bg:
                                b_excess += 1
                # Require a substantial shared motif; ties favor the shorter
                # offset and the panel pair with a clearer one-sided extension.
                excess = max(a_excess, b_excess)
                if common < height * 4 or fg_shared < height:
                    continue
                score = (common, excess, fg_shared, -abs(shift), -a0, -b0)
                if best_pair is None or score > best_pair[0]:
                    best_pair = (score, a0, b0, height, shift, a_excess, b_excess)

    if best_pair is None:
        return out

    _, a0, b0, height, shift, a_excess, b_excess = best_pair
    # The panel with more unmatched motif cells is the source. Mark the
    # corresponding background cells in the other panel with color 1.
    a_is_source = a_excess >= b_excess
    for dr in range(height):
        ra, rb = a0 + dr, b0 + dr
        row_a, row_b = grid[ra], grid[rb]
        for c in range(max(0, -shift), w):
            d = c + shift
            if not 0 <= d < w:
                continue
            va, vb = row_a[c], row_b[d]
            if a_is_source:
                if va != bg and vb == bg:
                    out[rb][d] = 1
            else:
