    """Mark cells missing from the earlier of two aligned motif bands."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    bands = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        bands.append((start, r))

    # Repeated instances are vertically separated bands. The later instance
    # supplies the colored cells missing from the first, at identical offsets.
    candidates = []
    for i, (a0, a1) in enumerate(bands):
        for b0, b1 in bands[i + 1:]:
            if a1 - a0 != b1 - b0:
                continue
            height = a1 - a0
            shared = sum((grid[a0+dr][c] != bg) == (grid[b0+dr][c] != bg)
                         for dr in range(height) for c in range(w))
            missing = sum(grid[a0+dr][c] == bg and grid[b0+dr][c] != bg
                          for dr in range(height) for c in range(w))
            if missing:
                candidates.append((shared, missing, -a0, a0, b0, height))
    if not candidates:
        return out
    _, _, _, a0, b0, height = max(candidates)
    for dr in range(height):
        for c in range(w):
            if grid[a0+dr][c] == bg and grid[b0+dr][c] != bg:
                out[a0+dr][c] = 1
    return out

if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin)), separators=(",", ":")))
