    """Copy the upper pattern into its vertically repeated lower panel."""
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    bands = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        a = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        bands.append((a, r))

    # Align equal-height motif bands, allowing a small horizontal displacement.
    best = None
    for i, (a0, a1) in enumerate(bands):
        for b0, b1 in bands[i + 1:]:
            if a1-a0 != b1-b0:
                continue
            n = a1-a0
            for shift in range(-3, 4):  # lower col = upper col + shift
                matches = total = 0
                for dr in range(n):
                    for c in range(w):
                        d = c+shift
                        if 0 <= d < w:
                            matches += ((grid[a0+dr][c] != bg) == (grid[b0+dr][d] != bg))
                            total += 1
                score = (matches, -abs(shift), -a0)
                if best is None or score > best[0]:
                    best = (score, a0, b0, n, shift)
    if best is None:
        return out

    _, a0, b0, n, shift = best
    # Paint only empty cells in the later panel where its aligned source has
    # foreground; retain the source and all unrelated cells.
    for dr in range(n):
        for c in range(w):
            d = c + shift
            if 0 <= d < w and grid[a0+dr][c] != bg and grid[b0+dr][d] == bg:
                out[b0+dr][d] = 1
    return out

if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin)), separators=(",", ":")))
